const allowed=()=>!signal()&&read()?.analytics===true;
function page(){const raw=(location.hash.startsWith('#/')?location.hash.slice(1):location.pathname).split(/[?#]/)[0];if(/^\/(admin|api|auth|signin|studio|workspace|account|billing-test)(\/|$)/.test(raw))return null;const first=raw.split('/').filter(Boolean)[0]||'home';return '/'+(first==='home'?'':/^[a-z-]{1,35}$/.test(first)?first:'other');}
